from playwright.sync_api import sync_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
widths = [(1920,930),(1440,900),(1280,800),(1024,768),(768,1024),(390,844),(320,568)]

with sync_playwright() as p:
    b = p.chromium.launch()
    for w,h in widths:
        pg = b.new_page(viewport={"width":w,"height":h})
        pg.goto(URL)
        pg.wait_for_timeout(700)
        r = pg.evaluate("""() => {
          const bands = Array.from(document.querySelectorAll('.step-band'));
          const bandH = getComputedStyle(document.getElementById('process')).getPropertyValue('--band-h');
          const sheet = document.querySelector('.process-sheet');
          const sheetRect = sheet ? sheet.getBoundingClientRect() : null;
          const out = bands.map((band, i) => {
            const p = band.querySelector('.process-p');
            const title = band.querySelector('.process-step-title');
            const num = band.querySelector('.ledger-num');
            const pcs = getComputedStyle(p);
            const range = document.createRange();
            range.selectNodeContents(p);
            const rects = range.getClientRects();
            return {
              i: i+1,
              pFontSize: pcs.fontSize,
              pColor: pcs.color,
              rows: rects.length,
              bandScrollH: band.scrollHeight,
              titleFontSize: getComputedStyle(title).fontSize,
              numFontSize: num ? getComputedStyle(num).fontSize : null,
            };
          });
          return { bandH, sheetWidth: sheetRect ? sheetRect.width : null, innerWidth: window.innerWidth, bands: out };
        }""")
        print(w, h, "bandH=", r["bandH"], "sheetW=", r["sheetWidth"], "sheetW/innerW=", (r["sheetWidth"]/w if r["sheetWidth"] else None))
        for b_ in r["bands"]:
            print("  ", b_)
        pg.close()
    b.close()

