    }
    var fri = stageR.bottom - lowest;
    var tickRects = [];
    for (var ki = 0; ki < tickEls.length; ki++) tickRects.push(tickEls[ki].getBoundingClientRect());
    var xs = [x1, x2, x3, x4];
    for (var xi = 0; xi < 4; xi++){
      var hitsTick = tickRects.some(function(r){ return xs[xi] >= r.left - 16 && xs[xi] <= r.right + 16; });
