from playwright.sync_api import sync_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

with sync_playwright() as p:
    b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
    for w, h in [(1920, 930), (1440, 900), (390, 844)]:
        pg = b.new_page(viewport={"width": w, "height": h})
        pg.goto(URL + "?preview=tes-till-ritning-4")
        pg.wait_for_timeout(1200)
        r = pg.evaluate("""() => {
          const ch = document.querySelector('.process-chapter');
          const cs = getComputedStyle(ch);
          const title = document.getElementById('process-title');
          const tr = title.getBoundingClientRect();
          const cr = ch.getBoundingClientRect();
          const h = document.querySelector('.seam-h');
          const hr = h.getBoundingClientRect();
          const sheet = document.querySelector('.process-sheet');
          const sr = sheet.getBoundingClientRect();
          return {
            x1: cs.getPropertyValue('--x1'), x2: cs.getPropertyValue('--x2'),
            x3: cs.getPropertyValue('--x3'), x4: cs.getPropertyValue('--x4'),
            up1: cs.getPropertyValue('--up1'), up2: cs.getPropertyValue('--up2'),
            up3: cs.getPropertyValue('--up3'), up4: cs.getPropertyValue('--up4'),
            dn: cs.getPropertyValue('--dn'),
            tx: cs.getPropertyValue('--tx'),
            titleTop: tr.top, chapterTop: cr.top,
            landingLineTop: hr.top,
            gapAboveTitle: tr.top - hr.top,
            sheetLeft: sr.left, sheetRight: sr.right, sheetWidth: sr.width,
          };
        }""")
        print(w, h, r)
        pg.close()
    b.close()

