1	from playwright.sync_api import sync_playwright
2	import sys
3	
4	URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
5	
6	HEADING_SEL = "h1, h2, h3, .ts, .statement, .close-mailto"
7	
8	SWEEP_JS = """
9	(sel) => {
10	  // Box-shorthand-aware inset() parser (1/2/3/4-token forms - a fixed-count
11	  // parser silently mis-skips 1- and 2-token serializations, see V3d R8-9
12	  // lore). Returns {top,right,bottom,left} in px, or null if not inset()/none.
13	  function parseInset(clipPath, w, h) {
14	    const m = /^inset\\(([^)]+)\\)/.exec(clipPath);
15	    if (!m) return null;
16	    const raw = m[1].trim().split(/\\s+/);
17	    function val(tok, base) { return tok.endsWith('%') ? parseFloat(tok)/100*base : parseFloat(tok); }
18	    let top, right, bottom, left;
19	    if (raw.length === 1) { top = right = bottom = left = val(raw[0], h); }
20	    else if (raw.length === 2) { top = bottom = val(raw[0], h); right = left = val(raw[1], w); }
21	    else if (raw.length === 3) { top = val(raw[0], h); right = left = val(raw[1], w); bottom = val(raw[2], h); }
22	    else { top = val(raw[0], h); right = val(raw[1], w); bottom = val(raw[2], h); left = val(raw[3], w); }
23	    return { top, right, bottom, left };
24	  }
25	  const headings = Array.from(document.querySelectorAll(sel));
26	  const hits = [];
27	  for (const el of headings) {
28	    const cs = getComputedStyle(el);
29	    if (parseFloat(cs.opacity) < 0.05) continue;
30	    let rect = el.getBoundingClientRect();
31	    if (rect.width <= 0 || rect.height <= 0) continue;
32	    // Restrict to the visible sub-rect after clip-path on the element itself
33	    // OR any ancestor (e.g. .cs h3 - the clip-path sits on the .cs <li>
34	    // parent, not the h3 - several stacked in the same grid cell; only the
35	    // unclipped slice is a real on-screen presence. Plan 057 Verification B2).
36	    let clipped = false;
37	    let node = el, depth = 0;
38	    while (node && node.nodeType === 1 && depth < 8) {
39	      depth++;
40	      const ncs = node === el ? cs : getComputedStyle(node);
41	      const nrect = node.getBoundingClientRect();
42	      const inset = parseInset(ncs.clipPath, nrect.width, nrect.height);
43	      if (inset) {
44	        const vTop = Math.max(rect.top, nrect.top + inset.top);
45	        const vBottom = Math.min(rect.bottom, nrect.bottom - inset.bottom);
46	        const vLeft = Math.max(rect.left, nrect.left + inset.left);
47	        const vRight = Math.min(rect.right, nrect.right - inset.right);
48	        rect = { top: vTop, bottom: vBottom, left: vLeft, right: vRight };
49	        clipped = true;
50	      }
51	      node = node.parentElement;
52	    }
53	    if (clipped && (rect.left >= rect.right || rect.top >= rect.bottom)) continue; // fully clipped
54	    const vw = window.innerWidth, vh = window.innerHeight;
55	    const left = Math.max(0, rect.left), right = Math.min(vw, rect.right);
56	    const top = Math.max(0, rect.top), bottom = Math.min(vh, rect.bottom);
57	    if (left >= right || top >= bottom) continue;
58	    for (let iy = 0; iy < 3; iy++) {
59	      for (let ix = 0; ix < 3; ix++) {
60	        const px = left + (right-left) * (ix+0.5)/3;
61	        const py = top + (bottom-top) * (iy+0.5)/3;
62	        const hitEl = document.elementFromPoint(px, py);
63	        if (!hitEl) continue;
64	        const isDescendant = el === hitEl || el.contains(hitEl);
65	        if (!isDescendant) {
66	          hits.push({ heading: el.tagName + '.' + el.className, px: Math.round(px), py: Math.round(py), hitTag: hitEl.tagName, hitCls: hitEl.className });
67	        }
68	      }
69	    }
70	  }
71	  return hits;
72	}
73	"""
74	
75	def sweep(pg, width, height, step=20):
76	    pg.set_viewport_size({"width": width, "height": height})
77	    pg.goto(URL)
78	    pg.wait_for_timeout(600)
79	    total_h = pg.evaluate("document.documentElement.scrollHeight")
80	    all_hits = []
81	    y = 0
82	    frame = 0
83	    while y <= total_h:
84	        pg.evaluate("window.scrollTo(0, " + str(y) + ")")
85	        pg.wait_for_timeout(20)
86	        hits = pg.evaluate(SWEEP_JS, HEADING_SEL)
87	        for h in hits:
88	            h["scrollY"] = y
89	            h["frame"] = frame
90	        all_hits.extend(hits)
91	        y += step
92	        frame += 1
93	    return all_hits, frame
94	
95	if __name__ == "__main__":
96	    inject_old = "--inject-old" in sys.argv
97	    widths = [(1920,930),(1440,900),(768,1024),(390,844)]
