from playwright.sync_api import sync_playwright
from PIL import Image
import io

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

with sync_playwright() as p:
    b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
    pg = b.new_page(viewport={"width": 1440, "height": 900})
    pg.goto(URL + "?preview=tes-till-ritning-2")
    pg.wait_for_timeout(1200)
    r = pg.evaluate("""() => {
      const ch = document.querySelector('.process-chapter');
      const cs = getComputedStyle(ch);
      const cr = ch.getBoundingClientRect();
      const x2css = parseFloat(cs.getPropertyValue('--x2'));
      return { x2: cr.left + x2css, chapterTop: cr.top };
    }""")
    shot = pg.screenshot()
    img = Image.open(io.BytesIO(shot))
    px = img.load()
    x = round(r["x2"])
    ctop = round(r["chapterTop"])
    print("x2 device px:", x, "chapterTop:", ctop)
    # sample a vertical strip crossing the boundary (chapterTop is the "kant")
    for dy in range(-40, 41, 4):
        y = ctop + dy
        if 0 <= y < img.size[1]:
            c = px[x, y]
            print(dy, y, c)
    pg.close()
    b.close()

