from playwright.sync_api import sync_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

def relative_luminance(rgb):
    def lin(c):
        c = c / 255
        return c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4
    r, g, b = rgb
    return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b)

def contrast(a, b):
    la, lb = relative_luminance(a), relative_luminance(b)
    lighter, darker = max(la, lb), min(la, lb)
    return (lighter + 0.05) / (darker + 0.05)

with sync_playwright() as p:
    b = p.chromium.launch()
    pg = b.new_page(viewport={"width": 1440, "height": 900})
    pg.goto(URL + "?preview=tes-till-ritning-0")
    pg.wait_for_timeout(1000)
    r = pg.evaluate("""() => {
      const title = document.getElementById('process-title');
      const cs = getComputedStyle(title);
      const bgEl = document.querySelector('.process-chapter');
      const bgCs = getComputedStyle(bgEl.closest('#process') || bgEl);
      return { color: cs.color, bgColor: getComputedStyle(document.getElementById('process')).backgroundColor, tx: getComputedStyle(document.querySelector('.process-chapter')).getPropertyValue('--tx') };
    }""")
    print(r)
    pg.close()
    b.close()

