from playwright.sync_api import sync_playwright
from PIL import Image
import io

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

def relative_luminance(rgb):
    def lin(c):
        c = c / 255
        return c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4
    r, g, bch = rgb
    return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(bch)

def contrast(a, bg):
    la, lb = relative_luminance(a), relative_luminance(bg)
    lighter, darker = max(la, lb), min(la, lb)
    return (lighter + 0.05) / (darker + 0.05)

with sync_playwright() as p:
    b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
    pg = b.new_page(viewport={"width": 1440, "height": 900})
    pg.goto(URL)
    pg.wait_for_timeout(700)
    pg.evaluate("""() => {
      const el = document.querySelector('.process-chapter');
      const rect = el.getBoundingClientRect();
      const top = rect.top + window.scrollY;
      const height = el.offsetHeight, vh = window.innerHeight;
      const p = 0.25;
      window.scrollTo(0, Math.round(top + p * (height + vh) - vh));
      window.dispatchEvent(new Event('resize'));
    }""")
    pg.wait_for_timeout(1000)
    r = pg.evaluate("""() => {
      const title = document.getElementById('process-title');
      const tr = title.getBoundingClientRect();
      const bg = getComputedStyle(document.getElementById('process')).backgroundColor;
      return { top: tr.top, left: tr.left, bottom: tr.bottom, right: tr.right, bg };
    }""")
    shot = pg.screenshot()
    img = Image.open(io.BytesIO(shot))
    px = img.load()
    # sample multiple points within the glyph strokes near the top of first letter
    cy = int((r["top"] + r["bottom"]) / 2)
    cy = max(0, min(img.size[1]-1, cy))
    brightest = (0,0,0)
    for x in range(max(0,int(r["left"])), min(img.size[0], int(r["right"])), 2):
        c = px[x, cy][:3]
